// Extrai tudo com valores seguros. Nunca quebra.
const b = $json.body || {};
const p = b.payload || {};
const media = p.media || {};
const mediaUrl = media.url ? String(media.url).replace('localhost:3000','waha:3000') : '';
const mime = String(media.mimetype || '');
const ehAudio = !!mediaUrl && mime.indexOf('audio') === 0;

// Video, imagem, figurinha, documento, localizacao... chegam sem texto.
// Texto vazio derruba o agente (a IA recusa mensagem vazia), entao a midia
// vira uma descricao curta. O agente nao le o arquivo: so sabe que chegou.
let texto = String(p.body || '').trim();
if (!texto && !ehAudio) {
  let tipo = 'uma mensagem sem texto';
  if (mime.indexOf('video') === 0) tipo = 'um video';
  else if (mime === 'image/webp') tipo = 'uma figurinha';
  else if (mime.indexOf('image') === 0) tipo = 'uma imagem';
  else if (mime) tipo = 'um arquivo';
  else if (p.hasMedia) tipo = 'um arquivo de midia';
  texto = '[O cliente enviou ' + tipo + '. Voce nao consegue ver videos, imagens nem arquivos: '
    + 'diga isso com gentileza e peca para ele escrever o que precisa.]';
}

return [{ json: {
  chatId: p.from || '',
  toId: p.to || '',
  fromMe: p.fromMe === true,
  source: p.source || '',
  ehAudio: ehAudio,
  mediaUrl: mediaUrl,
  texto: texto
}}];

