INSERT INTO pausa_humana (chat_id, motivo)
SELECT t.alvo, 'Atendente humano assumiu' FROM (
  SELECT coalesce(NULLIF('{{ $json.toId }}',''), NULLIF('{{ $json.chatId }}','')) AS alvo
) t
WHERE t.alvo IS NOT NULL AND t.alvo NOT LIKE '%@g.us'
ON CONFLICT (chat_id) DO UPDATE SET pausado_em = now(), motivo = EXCLUDED.motivo;

