// Caminho TEXTO: repassa o que veio.
// Remove o delimitador $txt$ para o texto do cliente nunca quebrar a query SQL.
const limpaSql = (s) => String(s || '').split('$txt$').join('');
return [{ json: { chatId: $json.chatId || '', texto: limpaSql($json.texto) } }];

// ============================================================
//  CEREBRO DA DECISAO
//  Detecta idioma (com memoria), identifica o tema e escolhe o audio.
//  Le SO do que chegou. Nunca referencia outro no.
// ============================================================
// Mude para true depois de colocar seus audios na pasta audios/ (veja audios/LEIA-ME.md)
const USAR_AUDIOS = false;

const d = $json || {};
const chatId = d.chat_id || '';
const texto = d.texto || '';
const pausado = (typeof d.pausado === 'number') ? d.pausado : 0;
const msgs = (typeof d.msgs === 'number') ? d.msgs : 99;
const jaEnviados = (d.ja_enviados || '').split(',');
const idiomaSalvo = d.idioma_salvo || '';

const bruto = texto.toLowerCase();
const limpo = bruto.normalize('NFD').replace(/[̀-ͯ]/g, '');

// procura palavra inteira (evita 'ola' casar dentro de 'hola')
function tem(palavra) {
  const p = palavra.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^a-z0-9])' + p + '([^a-z0-9]|$)').test(limpo);
}
function algum(lista) { return lista.some(tem); }

// ---------- IDIOMA ----------
// palavras que so existem em espanhol
const ES = ['hola','gracias','buenos','buenas','necesito','quiero','puedo','impresora',
  'usted','ustedes','senor','disculpe','ayuda','el','los','las','un','una','del','al',
  'con','y','hay','muy','mi','su','yo','es','son','tiene','puede','hacer','cuando',
  'donde','tambien','pero','ahora','esto','eso','soy','estoy','estan','mismo','tengo','si'];
// palavras que so existem em portugues
const PT = ['oi','ola','obrigado','obrigada','bom','boa','voce','voces','preciso',
  'impressora','ajuda','um','uma','do','da','dos','das','com','e','muito','meu','minha',
  'seu','sua','tem','fazer','nao','isso','ele','ela','quando','onde','entao','ja','ta',
  'pra','pro','ate','tudo','sou','estou','estao','mesmo','tenho','esta','vou','aqui'];

let es = 0, pt = 0;
for (const m of ES) { if (tem(m)) es++; }
for (const m of PT) { if (tem(m)) pt++; }
if (/[¿¡ñ]/.test(bruto)) es += 4;   // ¿ ¡ ñ
if (/[ãõç]/.test(bruto)) pt += 4;   // ã õ ç

let idioma;
if (es === pt) {
  // sem sinal claro (ex.: "ok", "si"): usa o idioma ja conhecido do cliente
  idioma = idiomaSalvo || 'pt';
} else {
  idioma = (es > pt) ? 'es' : 'pt';
}
// so vale salvar quando houve deteccao confiante
const salvarIdioma = (es !== pt) && (idioma !== idiomaSalvo);

// ---------- TEMA ----------
const temImpressora = algum(['impressora','impresora','imprimir','imprime','impressao',
  'impresion','printer','comanda','nao imprime','no imprime']);
const temErroTecnico = algum(['erro','error','bug','travou','travando','travado',
  'fora do ar','caiu','lento','lenta','falha','falla','nao funciona','no funciona',
  'nao carrega','no carga','nao abre','no abre','deu problema']);

// ---------- QUAL AUDIO ----------
// 1o contato: saudacao. Depois: audio do tema, uma vez a cada 24h.
let audio = '';
if (msgs === 0) {
  audio = 'saudacao-' + idioma;
} else if (temImpressora) {
  audio = 'impressora-' + idioma;
} else if (temErroTecnico) {
  audio = 'erro-tecnico-' + idioma;
}
if (audio && jaEnviados.indexOf(audio) !== -1) { audio = ''; }
if (!USAR_AUDIOS) { audio = ''; }

return [{ json: {
  chatId: chatId,
  texto: texto,
  pausado: pausado,
  msgs: msgs,
  idioma: idioma,
  idiomaSalvo: idiomaSalvo,
  salvarIdioma: salvarIdioma,
  audio: audio,
  temAudio: audio !== ''
}}];

