// carrega tudo que o ramo do agente precisa.
// Se um audio foi enviado, avisa o agente para complementar sem repetir.
const d = $json || {};
let nota = '';
if (d.audio && d.audio.indexOf('impressora') === 0) {
  nota = '\n\n[Sistema: um audio com orientacoes de impressora ja foi enviado ao cliente. Complemente de forma breve, sem repetir o passo a passo.]';
} else if (d.audio && d.audio.indexOf('erro-tecnico') === 0) {
  nota = '\n\n[Sistema: um audio sobre erros tecnicos ja foi enviado ao cliente. Complemente de forma breve, sem repetir o que o audio explicou.]';
} else if (d.audio && d.audio.indexOf('saudacao') === 0) {
  nota = '\n\n[Sistema: um audio de boas-vindas ja foi enviado. Nao se reapresente, va direto ao ponto.]';
}
return [{ json: {
  chatId: d.chatId || '',
  texto: d.texto || '',
  idioma: d.idioma || 'pt',
  audio: d.audio || '',
  temAudio: d.temAudio === true,
  textoParaAgente: (d.texto || '') + nota
}}];

// Plano B: se o Agente falhar, manda mensagem de espera no idioma certo.
const g = $('Guarda dados').first().json;
let out = '';
try { out = $json.output || ''; } catch (e) {}
if (!out || String(out).trim() === '') {
  out = (g.idioma === 'es')
    ? 'Estoy con una inestabilidad tecnica por aqui, pero en un momento te respondo.'
    : 'Estou com uma instabilidade tecnica por aqui, mas ja ja te respondo.';
}
return [{ json: { chatId: g.chatId || '', resposta: String(out) } }];

// Junta o estado da sessao com o QR (quando existir).
// O WAHA devolve {mimetype, data} com o base64 quando pedimos JSON.
const s = $('WAHA sessao').first().json || {};
const status = s.status || 'DESCONHECIDO';
let qr = null;
try {
  const q = $('WAHA QR').first().json || {};
  if (q.data && String(q.data).length > 100) {
    qr = 'data:' + (q.mimetype || 'image/png') + ';base64,' + q.data;
  }
} catch (e) {}
const rotulos = {
  WORKING: 'Conectado', STARTING: 'Iniciando', SCAN_QR_CODE: 'Aguardando leitura do QR',
  STOPPED: 'Parado', FAILED: 'Com falha' };
return [{ json: {
  ok: true,
  status: status,
  rotulo: rotulos[status] || status,
  conectado: status === 'WORKING',
  parado: status === 'STOPPED' || status === 'FAILED',
  numero: s.me ? s.me.id : null,
  perfil: s.me ? s.me.pushName : null,
  qr: qr
}}];
